import {journeysForPerson} from './document-model.mjs';
import {checkinBookings} from './checkin.mjs';
import {vehicleForPerson,participantRole} from './transport.mjs';
export const personalEmail=s=>String(s||'').trim().toLowerCase();
export function sharedSnapshot(trip){return {id:trip.id,name:trip.name,sport:trip.sport||'',destination:trip.destination||'',start:trip.start||'',end:trip.end||'',hotel:trip.hotel||'',hotelAddress:trip.hotelAddress||'',coordinator:trip.coordinator||'',phone:trip.phone||'',people:trip.people.map(p=>({id:p.id,name:p.name,email:personalEmail(p.email),role:participantRole(p.role),travelMode:p.travelMode||'Avió',ticket:p.ticket||'Pendent',checkin:p.checkin||'Pendent',notes:p.notes||'',journeys:journeysForPerson(trip,p.id),bookings:checkinBookings(trip,p.id).map(({document,...booking})=>booking),transports:['Anada','Tornada'].map(direction=>{const v=vehicleForPerson(trip,p,direction);return {direction,name:v?.name||'',driver:v?.driver||'',phone:v?.phone||'',origin:v?.origin||'',departure:v?.departure||'',pickupLocation:v?.pickupLocation||'',pickupTime:v?.pickupTime||'',isDriver:v?.driverId===p.id}})}))};}
export function validateSnapshot(trip){if(!trip||typeof trip.id!=='string'||!trip.id||trip.id.length>100||typeof trip.name!=='string'||!Array.isArray(trip.people)||trip.people.length>2000)throw Error('Viatge no vàlid.');const ids=new Set(),emails=new Set();for(const p of trip.people){if(!p.id||typeof p.id!=='string'||typeof p.name!=='string'||ids.has(p.id))throw Error('Participants no vàlids o repetits.');ids.add(p.id);p.email=personalEmail(p.email);if(p.email){if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.email))throw Error(`Revisa l’email de ${p.name}.`);if(emails.has(p.email))throw Error('Cada participant ha de tenir un email personal diferent.');emails.add(p.email);}}return trip;}
export function personalView(trip,email){const people=trip.people.filter(p=>personalEmail(p.email)===personalEmail(email)&&p.email);return people.map(person=>({id:trip.id,name:trip.name,sport:trip.sport||'',destination:trip.destination,start:trip.start,end:trip.end,hotel:trip.hotel,hotelAddress:trip.hotelAddress||'',coordinator:trip.coordinator,phone:trip.phone,person}));}
